size_t cp_reference_grid_count(void) {
    return sizeof(cp_reference_grid) / sizeof(cp_reference_grid[0]);
}

cp_status cp_reference_grid_at(size_t index, cp_reference_color *out) {
    if (!out) return CP_ERR_ARGUMENT;
    if (index >= cp_reference_grid_count()) return CP_ERR_NOT_FOUND;
    *out = cp_reference_grid[index];
    return CP_OK;
}

cp_status cp_reference_grid_nearest(cp_lab value, cp_reference_color *out,
                                    double *distance) {
    if (!out) return CP_ERR_ARGUMENT;
    double best = DBL_MAX;
    size_t best_index = 0;
    for (size_t i = 0; i < cp_reference_grid_count(); ++i) {
        double current = cp_delta_e_2000(value, cp_reference_grid[i].lab);
        if (current < best) {
            best = current;
            best_index = i;
        }
    }
    *out = cp_reference_grid[best_index];
    if (distance) *distance = best;
    return CP_OK;
}

cp_status cp_reference_grid_quantize(cp_rgb value, cp_rgb *out) {
    if (!out) return CP_ERR_ARGUMENT;
    cp_xyz xyz = cp_srgb_to_xyz(value);
    cp_xyz d65 = {0.95047, 1.0, 1.08883};
    cp_lab lab = cp_xyz_to_lab(xyz, d65);
    cp_reference_color nearest;
    cp_status status = cp_reference_grid_nearest(lab, &nearest, NULL);
    if (status != CP_OK) return status;
    out->r = nearest.red / 255.0;
    out->g = nearest.green / 255.0;
    out->b = nearest.blue / 255.0;
    return CP_OK;
}
